<?php
namespace Tests\Feature;use App\Models\{FootballMatch,MatchEvent,Team,User};use App\Services\MythGrammarService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PhaseTwoExperienceTest extends TestCase {use RefreshDatabase;
 public function test_myth_grammar_translates_match_events():void{[$match,$team]=$this->match();MatchEvent::create(['football_data_id'=>991,'match_id'=>$match->id,'match_football_data_id'=>$match->football_data_id,'team_id'=>$team->id,'team_football_data_id'=>$team->football_data_id,'type'=>'goal','minute'=>88,'player_name'=>'Ayo Blade']);$story=app(MythGrammarService::class)->tell($match);$this->assertStringContainsString('raid lands',$story['story']);$this->assertStringContainsString('Ayo Blade',$story['story']);}
 public function test_supporter_can_claim_only_one_daily_reward():void{$user=User::factory()->create();$this->actingAs($user)->post(route('supporter.daily'))->assertRedirect();$this->actingAs($user->fresh())->post(route('supporter.daily'))->assertRedirect();$this->assertSame(10,$user->fresh()->matchday_points);$this->assertSame(1,$user->fresh()->current_streak);}
 public function test_creator_application_is_moderated():void{$user=User::factory()->create();$this->actingAs($user)->post(route('creator.apply'),['display_name'=>'Pitch Voice','bio'=>str_repeat('Local football reporting. ',3),'speciality'=>'Academies'])->assertRedirect();$this->assertDatabaseHas('creator_profiles',['user_id'=>$user->id,'status'=>'pending']);}
 private function match():array{$league=\DB::table('leagues')->insertGetId(['football_data_id'=>700,'name'=>'League','created_at'=>now(),'updated_at'=>now()]);$home=Team::create(['football_data_id'=>701,'name'=>'Lions']);$away=Team::create(['football_data_id'=>702,'name'=>'Eagles']);$m=FootballMatch::withoutEvents(fn()=>FootballMatch::create(['football_data_id'=>703,'league_id'=>$league,'league_football_data_id'=>700,'home_team_id'=>$home->id,'home_team_football_data_id'=>701,'away_team_id'=>$away->id,'away_team_football_data_id'=>702,'match_date'=>now(),'status'=>'FINISHED','home_score'=>1,'away_score'=>0]));return[$m,$home];}
}
